function findDuplicates(arr) {
  const result = [];
  for (let i = 0; i < arr.length; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      if (arr[i] === arr[j]) result.push([i, j]);
    }
  }
  return result;
}
```
This runs in O(n) time complexity.
